// This file is generated by AI.

// 配音编辑模式的可见性与开关规则测试。
//
// 规则来自用户的明确要求, 必须精确遵守:
// * 没开全局配音 (配音工作台) 时, 一律不显示场景卡上的麦克风开关;
// * 开了之后, 只显示**处于配音编辑模式**的场景卡上的麦克风开关;
// * 普通场景卡上的划线麦克风不显示 —— 除非该卡已被选中;
// * 进入 / 退出配音编辑模式只有一个入口: 那个麦克风开关本身。
//
// "没有任何自动进入" 是这里的核心: 打开工作台或切换选项卡都不得改变任何场景的
// 配音编辑模式, 否则会出现"切到的每个场景都变成配音卡"以及"点了麦克风没反应
// (被自动规则覆盖), 切走再切回来才发现生效"。

import { beforeEach, describe, expect, it } from 'vitest';

import { shouldShowVoiceToggle, useAppStore } from '../src/state/store';
import { makeSceneTab } from '../src/tabs/model';
import {
  activeSceneInVoiceMode,
  isSceneInVoiceMode,
  setSceneVoiceMode,
  toggleVoiceWorkbench,
  voiceWorkbenchOpen,
} from '../src/voice/mode';

const sceneA = 'C:\\project\\game\\scene\\a.txt';
const sceneB = 'C:\\project\\game\\scene\\b.txt';

function resetStore(): void {
  useAppStore.setState({
    tabs: [],
    activeTabId: null,
    documents: [],
    voiceModePaths: [],
  });
  for (const path of [sceneA, sceneB]) {
    useAppStore.getState().openDocument({
      path,
      name: path.split('\\').pop() ?? path,
      uri: `file:///${path}`,
      content: '爱音:台词;\n',
      dirty: false,
      isScene: true,
    });
  }
}

/** 打开两张场景卡 (B 为当前卡) 并返回它们的选项卡 */
function openTwoScenes() {
  const tabA = makeSceneTab(sceneA, 'a.txt');
  const tabB = makeSceneTab(sceneB, 'b.txt');
  useAppStore.getState().openTab(tabA);
  useAppStore.getState().openTab(tabB);
  return { tabA, tabB };
}

/** 按当前的 store 状态判定某个场景卡是否显示麦克风开关 */
function toggleVisible(tab: ReturnType<typeof makeSceneTab>): boolean {
  const state = useAppStore.getState();
  return shouldShowVoiceToggle({
    workbenchOpen: voiceWorkbenchOpen(),
    activeTabId: state.activeTabId,
    tab,
    voiceModePaths: state.voiceModePaths,
  });
}

describe('配音编辑模式: 没有任何自动进入', () => {
  beforeEach(resetStore);

  it('打开工作台不会让任何场景进入配音编辑模式', () => {
    const { tabA, tabB } = openTwoScenes();
    expect(tabA.id).not.toBe(tabB.id);

    toggleVoiceWorkbench();

    expect(voiceWorkbenchOpen()).toBe(true);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
    expect(isSceneInVoiceMode(sceneB)).toBe(false);
  });

  it('切换选项卡不会让任何场景进入配音编辑模式', () => {
    const { tabA } = openTwoScenes();
    toggleVoiceWorkbench();

    // 工作台 → A → B → A: 一路切换都不应开启配音编辑模式
    useAppStore.getState().activateTab(tabA.id);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);

    const tabB = useAppStore.getState().tabs.find((tab) => tab.kind === 'scene' && tab.path === sceneB)!;
    useAppStore.getState().activateTab(tabB.id);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);

    useAppStore.getState().activateTab(tabA.id);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);
  });

  it('打开新场景卡也不会自动进入 (工作台打开期间)', () => {
    useAppStore.getState().openTab(makeSceneTab(sceneA, 'a.txt'));
    toggleVoiceWorkbench();
    useAppStore.getState().openTab(makeSceneTab(sceneB, 'b.txt'));

    expect(useAppStore.getState().voiceModePaths).toEqual([]);
    expect(activeSceneInVoiceMode()).toBe(false);
  });

  it('关闭工作台会清空全部配音编辑模式', () => {
    const { tabA } = openTwoScenes();
    toggleVoiceWorkbench();
    useAppStore.getState().activateTab(tabA.id);
    setSceneVoiceMode(sceneA, true);
    expect(isSceneInVoiceMode(sceneA)).toBe(true);

    toggleVoiceWorkbench();
    expect(voiceWorkbenchOpen()).toBe(false);
    expect(useAppStore.getState().voiceModePaths).toEqual([]);
  });
});

describe('配音编辑模式: 麦克风开关的可见性', () => {
  beforeEach(resetStore);

  it('未打开工作台时任何场景卡都不显示开关', () => {
    const { tabA, tabB } = openTwoScenes();
    expect(toggleVisible(tabA)).toBe(false);
    expect(toggleVisible(tabB)).toBe(false);
  });

  it('切到场景卡后, 只有当前那张显示开关', () => {
    const { tabA, tabB } = openTwoScenes();
    toggleVoiceWorkbench();
    // 打开工作台后最前面是工作台选项卡, 此时没有场景卡显示开关
    expect(toggleVisible(tabB)).toBe(false);

    useAppStore.getState().activateTab(tabB.id);
    expect(toggleVisible(tabB)).toBe(true);
    expect(toggleVisible(tabA)).toBe(false);

    useAppStore.getState().activateTab(tabA.id);
    expect(toggleVisible(tabA)).toBe(true);
    expect(toggleVisible(tabB)).toBe(false);
  });

  it('切到非场景选项卡后, 原来那张卡上的划线麦克风消失', () => {
    const { tabB } = openTwoScenes();
    toggleVoiceWorkbench();
    useAppStore.getState().activateTab(tabB.id);
    expect(toggleVisible(tabB)).toBe(true);

    // 切到工作台 / 说明页这类非场景选项卡
    const workbench = useAppStore.getState().tabs.find((tab) => tab.kind === 'voice-workbench')!;
    useAppStore.getState().activateTab(workbench.id);
    expect(toggleVisible(tabB)).toBe(false);

    useAppStore.getState().openVoiceGuide();
    expect(toggleVisible(tabB)).toBe(false);
  });

  it('已进入配音编辑模式的卡始终显示开关 (无论是否选中)', () => {
    const { tabA, tabB } = openTwoScenes();
    toggleVoiceWorkbench();
    // 在 A 上开启配音编辑模式
    useAppStore.getState().activateTab(tabA.id);
    setSceneVoiceMode(sceneA, true);

    // 切到 B: A 不在选中态, 但它处于配音编辑模式, 仍要显示开关 (否则无法退出)
    useAppStore.getState().activateTab(tabB.id);
    expect(toggleVisible(tabA)).toBe(true);
    expect(toggleVisible(tabB)).toBe(true);
  });

  it('在非选中卡上关闭配音编辑模式后, 它不再显示开关', () => {
    const { tabA, tabB } = openTwoScenes();
    toggleVoiceWorkbench();
    useAppStore.getState().activateTab(tabA.id);
    setSceneVoiceMode(sceneA, true);
    useAppStore.getState().activateTab(tabB.id);

    // 等价于在 A 上点麦克风: 关闭之后 A 既没模式也不是当前卡 -> 不显示
    setSceneVoiceMode(sceneA, false);
    expect(toggleVisible(tabA)).toBe(false);
    expect(isSceneInVoiceMode(sceneA)).toBe(false);
  });

  it('非场景选项卡永不显示开关', () => {
    toggleVoiceWorkbench();
    const workbench = useAppStore.getState().tabs.find((tab) => tab.kind === 'voice-workbench')!;
    expect(
      shouldShowVoiceToggle({ workbenchOpen: true, activeTabId: workbench.id, tab: workbench, voiceModePaths: [] })
    ).toBe(false);
  });

  it('切换选项卡会清空光标记录 (避免新卡继承旧卡的行号)', () => {
    const { tabA, tabB } = openTwoScenes();
    toggleVoiceWorkbench();
    useAppStore.getState().setCursor({ path: sceneB, line: 12, column: 1 });
    expect(useAppStore.getState().cursor?.line).toBe(12);

    useAppStore.getState().activateTab(tabA.id);
    expect(useAppStore.getState().cursor).toBeNull();
    expect(tabB.id).not.toBe(tabA.id);
  });

  it('每个文档各自记住光标位置', () => {
    const { tabA, tabB } = openTwoScenes();
    useAppStore.getState().rememberCursor(sceneA, { line: 7, column: 1 });
    useAppStore.getState().rememberCursor(sceneB, { line: 20, column: 3 });
    expect(useAppStore.getState().cursors[sceneA]).toEqual({ line: 7, column: 1 });
    expect(useAppStore.getState().cursors[sceneB]).toEqual({ line: 20, column: 3 });
    // 切卡不清空留档 (切回来要能恢复)
    useAppStore.getState().activateTab(tabA.id);
    useAppStore.getState().activateTab(tabB.id);
    expect(useAppStore.getState().cursors[sceneA]).toEqual({ line: 7, column: 1 });
  });

  it('开关的开启与关闭是幂等的单入口 (不再被自动规则覆盖)', () => {
    const { tabA } = openTwoScenes();
    toggleVoiceWorkbench();
    useAppStore.getState().activateTab(tabA.id);

    setSceneVoiceMode(tabA.path, true);
    expect(isSceneInVoiceMode(tabA.path)).toBe(true);
    expect(toggleVisible(tabA)).toBe(true);

    setSceneVoiceMode(tabA.path, false);
    expect(isSceneInVoiceMode(tabA.path)).toBe(false);
    // 当前卡仍然显示开关, 因此可以再次点开
    expect(toggleVisible(tabA)).toBe(true);

    setSceneVoiceMode(tabA.path, true);
    expect(isSceneInVoiceMode(tabA.path)).toBe(true);
  });
});
